contract InvMutTest {
    C c;
    constructor() { c = new C(0, "", ""); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    function run(address target, uint256 mintedAmount) public {
        require(target != address(0));
        require(mintedAmount > 0);
        c.freezeAccount(target, true); if (__ESBMC_reverted()) return;
        uint256 bal0 = c.balanceOf(target); if (__ESBMC_reverted()) return;
        uint256 sup0 = c.totalSupply(); if (__ESBMC_reverted()) return;
        c.mintToken(target, mintedAmount); if (__ESBMC_reverted()) return;
        uint256 bal1 = c.balanceOf(target); if (__ESBMC_reverted()) return;
        uint256 sup1 = c.totalSupply(); if (__ESBMC_reverted()) return;
        assert(bal1 == bal0 + mintedAmount && sup1 == sup0 + mintedAmount);
    }
    receive() external payable {}
}

