    ERCDDAToken c;

    function setUp() public {
        c = new ERCDDAToken(0, "", "");
    }

    function _run(address target, uint256 mintedAmount) internal {
        vm.assume(target != address(0));
        vm.assume(mintedAmount > 0);
        try c.freezeAccount(target, true) {} catch { return; }
        uint256 bal0;
        try c.balanceOf(target) returns (uint256 __r) { bal0 = __r; } catch { return; }
        uint256 sup0;
        try c.totalSupply() returns (uint256 __r) { sup0 = __r; } catch { return; }
        try c.mintToken(target, mintedAmount) {} catch { return; }
        uint256 bal1;
        try c.balanceOf(target) returns (uint256 __r) { bal1 = __r; } catch { return; }
